"""Author-written optional coding challenges for all 99 lessons.

A hardcore challenge is a *new* application of the lesson, not the theory
example with its answer copied. They run on the standard JDK (no Spring/DB),
including simulations of higher-level topics. Keep all original IDs stable.
"""


def H(prompt, output, hint):
    assert len(prompt) >= 65 and output and len(hint) >= 55, prompt
    return dict(prompt=prompt, expectedOutput=output, hint=hint,
                explanation=f'Сопоставьте свой результат с ожидаемым выводом: {output!r}. {hint}')


