def R(prompt, options, correct, hint):
    assert len(prompt) >= 45 and len(options) == 4 and len(set(options)) == 4, prompt
    assert correct in 'abcd' and hint, prompt
    return dict(prompt=prompt, options=[dict(id=letter, label=label)
                                 for letter, label in zip('abcd', options)],
                correct=[correct], multiple=False, hint=hint,
                explanation=f'Верно: {options["abcd".index(correct)]}. {hint}')


